update public.question_answers set model_answer = '1) المخاليط غير المتجانسة: مخاليط لا تمتزج مكوناتها تمامًا معًا، أي يمكن تمييز كل منها، وهي نوعان: المعلق والغروي؛ مثل الوحل (معلق) أو الحليب (غروي). 2) المخاليط المتجانسة (المحاليل): مخاليط تحتوي على مذاب ومذيب لا يمكن التمييز بينهما عند النظر إلى المحلول؛ مثل الهواء أو ماء البحر أو الفولاذ. ويقبل أي مثال صحيح.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O02' and q.type = 'essay' and q.number = 1) and model_answer = '1) المخاليط غير المتجانسة: مخاليط لا تمتزج مكوناتها تمامًا معًا، أي يمكن تمييز كل منها، وهي نوعان: المعلق والغروي؛ مثل الوحل (معلق) أو الحليب (غروي). 2) المخاليط المتجانسة (المحاليل): مخاليط تحتوي على مذاب ومذيب لا يمكن التمييز بينهما عند النظر إلى المحلول؛ مثل الهواء أو ماء البحر أو الفولاذ.';
