update public.question_answers set model_answer = 'تُصنَّف المحاليل إلى غازية أو سائلة أو صلبة اعتمادًا على الحالة الفيزيائية للمذيب، في حين قد يكون المذاب غازًا أو سائلًا أو صلبًا. المحلول الغازي: الهواء؛ المذيب النيتروجين (غاز) والمذاب الأكسجين (غاز). المحلول السائل: ماء البحر؛ المذيب الماء (سائل) والمذاب كلوريد الصوديوم (صلب). المحلول الصلب: الفولاذ؛ المذيب الحديد (صلب) والمذاب الكربون (صلب). (ويقبل أي مثال صحيح).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O05' and q.type = 'essay' and q.number = 1) and model_answer = 'تُصنَّف المحاليل إلى غازية أو سائلة أو صلبة اعتمادًا على الحالة الفيزيائية للمذيب، في حين قد يكون المذاب غازًا أو سائلًا أو صلبًا. المحلول الغازي: الهواء؛ المذيب النيتروجين (غاز) والمذاب الأكسجين (غاز). المحلول السائل: ماء البحر؛ المذيب الماء (سائل) والمذاب كلوريد الصوديوم (صلب). المحلول الصلب: الفولاذ؛ المذيب الحديد (صلب) والمذاب الكربون (صلب). (تُقبل أمثلة أخرى من الجدول 1-2).';
