update public.questions set stem = 'يبيّن الجدول ذائبية بعض الأملاح في الماء عند درجات حرارة مختلفة (القيم بوحدة g/100 g H₂O). ما ذائبية KCl في الماء عند 60 °C؟', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O17' and q.type = 'mcq' and q.number = 1) and stem = 'يبيّن الجدول جزءًا من الجدول 1-4 (القيم بوحدة g/100 g H₂O). ما ذائبية KCl في الماء عند 60 °C؟';
update public.questions set stem = 'استعن بالبيانات الآتية لذائبية بعض الأملاح بوحدة g/100 g H₂O عند 0 و20 و60 و100 °C على الترتيب: Al₂(SO₄)₃: 31.2 (0 °C)، 36.4 (20 °C)، 59.2 (60 °C)، 89.0 (100 °C)؛ Li₂SO₄: 36.1، 34.8، 32.6 (لا قيمة عند 100 °C)؛ KCl: 28.0، 34.2، 45.8، 56.3. (أ) صف اتجاه تغير ذائبية كل مادة بارتفاع درجة الحرارة. (ب) احسب التغير في ذائبية كل مادة بين 0 °C و60 °C. (ج) أيّ المواد الثلاث تتأثر ذائبيتها بالحرارة أكثر؟ (د) صف كيف سيبدو منحنى ذائبية Li₂SO₄ مقارنة بمنحنى Al₂(SO₄)₃ لو رُسما.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O17' and q.type = 'essay' and q.number = 1) and stem = 'استعن ببيانات الجدول 1-4 (g/100 g H₂O): Al₂(SO₄)₃: 31.2 (0 °C)، 36.4 (20 °C)، 59.2 (60 °C)، 89.0 (100 °C)؛ Li₂SO₄: 36.1، 34.8، 32.6 (لا قيمة عند 100 °C)؛ KCl: 28.0، 34.2، 45.8، 56.3. (أ) صف اتجاه تغير ذائبية كل مادة بارتفاع درجة الحرارة. (ب) احسب التغير في ذائبية كل مادة بين 0 °C و60 °C. (ج) أيّ المواد الثلاث تتأثر ذائبيتها بالحرارة أكثر؟ (د) صف كيف سيبدو منحنى ذائبية Li₂SO₄ مقارنة بمنحنى Al₂(SO₄)₃ لو رُسما.';
update public.questions set stem = 'حدّد ذائبية كلٍّ من NaCl وCa(OH)₂ في الماء عند 20 °C وعند 100 °C، ثم صف أثر ارتفاع درجة الحرارة في ذائبية كلٍّ منهما. (NaCl: 35.9 عند 20 °C، 39.2 عند 100 °C؛ Ca(OH)₂: 0.173 عند 20 °C، 0.076 عند 100 °C، بوحدة g/100 g H₂O)', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O17' and q.type = 'essay' and q.number = 3) and stem = 'استعمل بيانات الجدول 1-4 لتحديد ذائبية كلٍّ من NaCl وCa(OH)₂ في الماء عند 20 °C وعند 100 °C، ثم صف أثر ارتفاع درجة الحرارة في ذائبية كلٍّ منهما. (NaCl: 35.9 عند 20 °C، 39.2 عند 100 °C؛ Ca(OH)₂: 0.173 عند 20 °C، 0.076 عند 100 °C، بوحدة g/100 g H₂O)';
update public.questions set stem = 'قارن بين المواد المتأينة القوية والمواد المتأينة الضعيفة والمواد غير المتأينة من حيث: (أ) سلوكها عند الذوبان في الماء. (ب) توصيل محاليلها للتيار الكهربائي. ثم اذكر مثالًا على المادة المتأينة القوية وآخر على المادة غير المتأينة.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O07' and q.type = 'essay' and q.number = 1) and stem = 'قارن بين المواد المتأينة القوية والمواد المتأينة الضعيفة والمواد غير المتأينة من حيث: (أ) سلوكها عند الذوبان في الماء. (ب) توصيل محاليلها للتيار الكهربائي. ثم اذكر مثالًا من الكتاب على المادة المتأينة القوية وآخر على المادة غير المتأينة.';
update public.question_answers set model_answer = '(أ) المتأينة القوية تتفكك في الماء وتنتج أيونات كثيرة، والمتأينة الضعيفة تنتج عددًا قليلًا من الأيونات، وغير المتأينة تذوب جزيئاتها دون أن تتأين. (ب) محاليل المتأينة القوية موصلة جيدة للتيار، ومحاليل المتأينة الضعيفة توصله توصيلًا ضعيفًا، ومحاليل غير المتأينة لا توصله. مثال المتأينة القوية: كلوريد الصوديوم NaCl، ومثال غير المتأينة: السكروز (أو الجليسرول). ويقبل أي مثال صحيح.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O07' and q.type = 'essay' and q.number = 1) and model_answer = '(أ) المتأينة القوية تتفكك في الماء وتنتج أيونات كثيرة، والمتأينة الضعيفة تنتج عددًا قليلًا من الأيونات، وغير المتأينة تذوب جزيئاتها دون أن تتأين. (ب) محاليل المتأينة القوية موصلة جيدة للتيار، ومحاليل المتأينة الضعيفة توصله توصيلًا ضعيفًا، ومحاليل غير المتأينة لا توصله. مثال المتأينة القوية: كلوريد الصوديوم NaCl، ومثال غير المتأينة: السكروز (أو الجليسرول).';
