update public.question_answers set model_answer = 'أقترح إضافة جليكول الإيثيلين، وهو مذاب غير متأين يُستعمل مانعًا للتجمد (ويقبل أي مانع تجمد غير متأين مناسب). إضافته تقلل درجة تجمد الماء في المبرد (ΔTf = Kf·m)، فلا يتجمد الماء عند 0 °C بل عند درجة أقل. ولأن المذاب غير متأين فإن كل 1 mol منه ينتج 1 mol من الجسيمات ولا يوصل محلوله التيار ويقلل التجمد كغيره من الخواص الجامعة. ونتوقع أن تنخفض درجة تجمد الماء المضاف إليه كلما زادت مولالية المذاب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O11' and q.type = 'essay' and q.number = 3) and model_answer = 'أقترح إضافة جليكول الإيثيلين، وهو مذاب غير متأين ومانع تجمد ورد ذكره في الكتاب. إضافته تقلل درجة تجمد الماء في المبرد (ΔTf = Kf·m)، فلا يتجمد الماء عند 0 °C بل عند درجة أقل. ولأن المذاب غير متأين فإن كل 1 mol منه ينتج 1 mol من الجسيمات ولا يوصل محلوله التيار ويقلل التجمد كغيره من الخواص الجامعة. ونتوقع أن تنخفض درجة تجمد الماء المضاف إليه كلما زادت مولالية المذاب.';
