update public.questions set stem = 'عرّف تميّه الأملاح، ثم اذكر الطريقتين اللتين يتفاعل بهما أيون الملح مع الماء، ومثّل لكل منهما بمعادلة.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O04' and q.type = 'essay' and q.number = 1) and stem = 'عرّف تميّه الأملاح، ثم اذكر الطريقتين اللتين يتفاعل بهما أيون الملح مع الماء، ومثّل لكل منهما بمعادلة من الكتاب.';
update public.question_answers set model_answer = 'تميّه الأملاح: عملية تتفاعل فيها الأملاح مع الماء. الطريقة الأولى: يستقبل الأيون السالب من الملح أيون هيدروجين من الماء، مثل: F⁻(aq) + H₂O(l) ⇌ HF(aq) + OH⁻(aq). الطريقة الثانية: يمنح الأيون الموجب من الملح أيون هيدروجين للماء، مثل: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq). ويقبل أي مثال صحيح.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O04' and q.type = 'essay' and q.number = 1) and model_answer = 'تميّه الأملاح: عملية تتفاعل فيها الأملاح مع الماء. الطريقة الأولى: يستقبل الأيون السالب من الملح أيون هيدروجين من الماء، مثل: F⁻(aq) + H₂O(l) ⇌ HF(aq) + OH⁻(aq). الطريقة الثانية: يمنح الأيون الموجب من الملح أيون هيدروجين للماء، مثل: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq).';
update public.questions set stem = 'في تجربة لاختبار محاليل أملاح بكاشف البروموثيمول الأزرق، ظهر لون أصفر في محلول NH₄Cl، وأخضر في محلول NaNO₃، وأزرق في محلول KF (التركيز 0.10 M لكل منها). فسّر هذه النتائج بتحديد الحمض والقاعدة اللذين يتكون منهما كل ملح وقوتهما، مع كتابة معادلة التميّه حيث يلزم.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O05' and q.type = 'essay' and q.number = 2) and stem = 'في تجربة الكتاب (الشكل 2-26) أعطى كاشف البروموثيمول الأزرق لونًا أصفر في محلول NH₄Cl، وأخضر في محلول NaNO₃، وأزرق في محلول KF (التركيز 0.10 M لكل منها). فسّر هذه النتائج بتحديد الحمض والقاعدة اللذين يتكون منهما كل ملح وقوتهما، مع كتابة معادلة التميّه حيث يلزم.';
update public.questions set stem = 'عند إضافة 0.01 mol من HCl إلى 1 L من الماء النقي (pH = 7.0)، تنخفض قيمة pH إلى:', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O06' and q.type = 'mcq' and q.number = 3) and stem = 'حسب الكتاب، عند إضافة 0.01 mol من HCl إلى 1 L من الماء النقي، تنخفض قيمة pH من 7.0 إلى:';
update public.question_answers set explanation = '[H⁺] = 0.01 mol ÷ 1 L = 0.01 M، فـ pH = −log 0.01 = 2.0؛ أي تنخفض pH من 7.0 إلى 2.0.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O06' and q.type = 'mcq' and q.number = 3) and explanation = '[H⁺] = 0.01 mol ÷ 1 L = 0.01 M، فـ pH = −log 0.01 = 2.0؛ وهو ما ذكره الكتاب: تنخفض pH من 7.0 إلى 2.0.';
