update public.question_answers set explanation = 'من المحاليل المنظمة في الدم محلول حمض الكربونيك والكربونات الهيدروجينية H₂CO₃/HCO₃⁻: CO₂ + H₂O ⇌ H₂CO₃ ⇌ H⁺ + HCO₃⁻.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 3) and explanation = 'ذكر الكتاب أن من المحاليل المنظمة في الدم محلول حمض الكربونيك والكربونات الهيدروجينية H₂CO₃/HCO₃⁻: CO₂ + H₂O ⇌ H₂CO₃ ⇌ H⁺ + HCO₃⁻.';
update public.questions set stem = 'لكي تكون البيئة صحية لقناديل البحر، يجب أن تبقى قيمة pH لمياه أحواض الأحياء المائية بين:', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 4) and stem = 'لكي تكون البيئة صحية لقناديل البحر (الشكل 2-27)، يجب أن تبقى قيمة pH لمياه أحواض الأحياء المائية بين:';
update public.question_answers set explanation = 'يجب أن تبقى قيمة pH للماء في أحواض الأحياء المائية بين 8.1 و8.4 لتكون البيئة صحية لقناديل البحر.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 4) and explanation = 'حسب الشكل 2-27 في الكتاب: يجب أن تبقى قيمة pH للماء في أحواض الأحياء المائية بين 8.1 و8.4.';
update public.questions set stem = 'اذكر ثلاثة أمثلة على أهمية بقاء قيمة pH ضمن مدى محدد في الكائنات الحية، مع ذكر المدى المطلوب في كل مثال.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'essay' and q.number = 1) and stem = 'اذكر ثلاثة أمثلة أوردها الكتاب على أهمية بقاء قيمة pH ضمن مدى محدد في الكائنات الحية، مع ذكر المدى المطلوب في كل مثال.';
update public.question_answers set model_answer = '1) الدم في جسم الإنسان: يجب أن يبقى pH بين 7.1 و7.7. 2) العصارة المعدية: يجب أن يبقى pH بين 1.6 و1.8 لتساعد على هضم أنواع معينة من الطعام. 3) قناديل البحر: يجب أن يبقى pH مياه أحواض الأحياء المائية بين 8.1 و8.4. ويحافظ الجسم على pH ضمن حدود معينة من خلال إنتاج محاليل منظمة. ويقبل أي مثال صحيح آخر مع مداه.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'essay' and q.number = 1) and model_answer = '1) الدم في جسم الإنسان: يجب أن يبقى pH بين 7.1 و7.7. 2) العصارة المعدية: يجب أن يبقى pH بين 1.6 و1.8 لتساعد على هضم أنواع معينة من الطعام. 3) قناديل البحر: يجب أن يبقى pH مياه أحواض الأحياء المائية بين 8.1 و8.4. ويحافظ الجسم على pH ضمن حدود معينة من خلال إنتاج محاليل منظمة.';
update public.questions set stem = 'يلزم أن تبقى قيمة pH ضمن مدى محدد في ثلاثة أوساط: الدم (7.1–7.7)، والعصارة المعدية (1.6–1.8)، ومياه أحواض قناديل البحر (8.1–8.4). رتّب هذه الأوساط تصاعديًا بحسب قيمة pH وحدّد طبيعة كل منها (حمضي، أو قريب من التعادل، أو قاعدي ضعيف)، ثم فسّر لماذا تحتاج هذه الأوساط إلى المحافظة على pH ضمن مدى ضيق.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'essay' and q.number = 3) and stem = 'يذكر الكتاب المدى المطلوب لقيمة pH في ثلاثة أوساط: الدم (7.1–7.7)، والعصارة المعدية (1.6–1.8)، ومياه أحواض قناديل البحر (8.1–8.4). رتّب هذه الأوساط تصاعديًا بحسب قيمة pH وحدّد طبيعة كل منها (حمضي، أو قريب من التعادل، أو قاعدي ضعيف)، ثم فسّر لماذا تحتاج هذه الأوساط إلى المحافظة على pH ضمن مدى ضيق.';
update public.questions set stem = 'قال طالب: «نقطة التكافؤ تكون دائمًا عند pH = 7، ولذلك تتطابق نقطة النهاية مع نقطة التكافؤ مهما كان الكاشف المستعمل». قوّم هذه العبارة بجزأيها، مع ذكر مثال.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O11' and q.type = 'essay' and q.number = 3) and stem = 'قال طالب: «نقطة التكافؤ تكون دائمًا عند pH = 7، ولذلك تتطابق نقطة النهاية مع نقطة التكافؤ مهما كان الكاشف المستعمل». قوّم هذه العبارة بجزأيها، مع ذكر مثال من الكتاب.';
update public.question_answers set model_answer = 'الجزء الأول غير صحيح: نقطة التكافؤ تكون عند pH = 7 في معايرة حمض قوي بقاعدة قوية فقط (مثل HCl مع NaOH)، أما في معايرة حمض ضعيف بقاعدة قوية (مثل HCOOH مع NaOH) فتقع بين pH 8 و9، وبعض المعايرات نقطة تكافئها أقل من 7؛ بسبب تفاعل الأملاح الناتجة مع الماء. الجزء الثاني غير صحيح: نقطة النهاية هي نقطة تغير لون الكاشف، ولكل كاشف مدى pH خاص، فلا تتطابق مع نقطة التكافؤ إلا إذا شمل مدى الكاشف قيمة pH عند التكافؤ؛ لذا يُختار البروموثيمول الأزرق لمعايرة حمض قوي بقاعدة قوية والفينولفثالين لمعايرة حمض ضعيف بقاعدة قوية. ويقبل أي مثال صحيح.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O11' and q.type = 'essay' and q.number = 3) and model_answer = 'الجزء الأول غير صحيح: نقطة التكافؤ تكون عند pH = 7 في معايرة حمض قوي بقاعدة قوية فقط (مثل HCl مع NaOH)، أما في معايرة حمض ضعيف بقاعدة قوية (مثل HCOOH مع NaOH) فتقع بين pH 8 و9، وبعض المعايرات نقطة تكافئها أقل من 7؛ بسبب تفاعل الأملاح الناتجة مع الماء. الجزء الثاني غير صحيح: نقطة النهاية هي نقطة تغير لون الكاشف، ولكل كاشف مدى pH خاص، فلا تتطابق مع نقطة التكافؤ إلا إذا شمل مدى الكاشف قيمة pH عند التكافؤ؛ لذا يُختار البروموثيمول الأزرق لمعايرة حمض قوي بقاعدة قوية والفينولفثالين لمعايرة حمض ضعيف بقاعدة قوية.';
