update public.question_answers set explanation = 'يُرمز لعدد التأكسد بالرمز n، مثل n(Cl) = +5 في KClO₃.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O04' and q.type = 'mcq' and q.number = 2) and explanation = 'يرمز الكتاب لعدد التأكسد بالرمز n، مثل n(Cl) = +5 في KClO₃.';
update public.questions set stem = 'وفق قواعد تحديد أعداد التأكسد، عدد تأكسد الذرة الأكثر كهروسالبية في الجزيء التساهمي يساوي:', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O04' and q.type = 'mcq' and q.number = 7) and stem = 'وفق قواعد الجدول 2-3، عدد تأكسد الذرة الأكثر كهروسالبية في الجزيء التساهمي يساوي:';
update public.question_answers set explanation = 'تنص القاعدة على أن عدد تأكسد الذرة الأكثر كهروسالبية في الجزيء أو الأيون المعقد هو الشحنة نفسها التي سيكون عليها لو كان أيونًا، مثل N في NH₃ (−3).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O04' and q.type = 'mcq' and q.number = 7) and explanation = 'تنص القاعدة 3 في الجدول 2-3 على أن عدد تأكسد الذرة الأكثر كهروسالبية في الجزيء أو الأيون المعقد هو الشحنة نفسها التي سيكون عليها لو كان أيونًا، مثل N في NH₃ (−3).';
