update public.question_answers set explanation = 'في المعادلة (ب) يظهر النيتروجين في HNO₃ في المتفاعلات وفي Cu(NO₃)₂ وNO₂ في النواتج، فيصعب وزنها بالطريقة التقليدية وتُوزن بطريقة عدد التأكسد؛ أما في المعادلات الأيونية البسيطة (أ) و(ج) و(د) فيظهر كل عنصر في مادة واحدة في كل جانب، فتناسبها طريقة نصف التفاعل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O07' and q.type = 'mcq' and q.number = 4) and explanation = 'في المعادلة (ب) يظهر النيتروجين في HNO₃ في المتفاعلات وفي Cu(NO₃)₂ وNO₂ في النواتج، فيصعب وزنها بالطريقة التقليدية وتُوزن بطريقة عدد التأكسد كما في المثال 3-3؛ أما في المعادلات الأيونية البسيطة (أ) و(ج) و(د) فيظهر كل عنصر في مادة واحدة في كل جانب، فتناسبها طريقة نصف التفاعل.';
