update public.question_answers set model_answer = 'العبارة خاطئة. القيمة صفر قيمة مُعيَّنة اتفاقًا ليُقاس عليها غيره، ولا تعني أن القطب لا يتفاعل. يحدث عنده أحد تفاعلين بحسب نصف الخلية الموصول به: اختزال 2H⁺(aq) + 2e⁻ → H₂(g)، أو أكسدة H₂(g) → 2H⁺(aq) + 2e⁻. مثال 1: عند توصيله بنصف خلية النحاس تتدفق الإلكترونات نحو النحاس، فيتأكسد H₂ عند قطب الهيدروجين (أنود). مثال 2: عند توصيله بنصف خلية الخارصين تتدفق الإلكترونات من الخارصين نحو قطب الهيدروجين، فتُختزل H⁺ عنده (كاثود). ويقبل أي مثال صحيح آخر.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O05' and q.type = 'essay' and q.number = 2) and model_answer = 'العبارة خاطئة. القيمة صفر قيمة مُعيَّنة اتفاقًا ليُقاس عليها غيره، ولا تعني أن القطب لا يتفاعل. يحدث عنده أحد تفاعلين بحسب نصف الخلية الموصول به: اختزال 2H⁺(aq) + 2e⁻ → H₂(g)، أو أكسدة H₂(g) → 2H⁺(aq) + 2e⁻. مثال 1: عند توصيله بنصف خلية النحاس تتدفق الإلكترونات نحو النحاس، فيتأكسد H₂ عند قطب الهيدروجين (أنود). مثال 2: عند توصيله بنصف خلية الخارصين تتدفق الإلكترونات من الخارصين نحو قطب الهيدروجين، فتُختزل H⁺ عنده (كاثود).';
