update public.question_answers set model_answer = 'لأن قيمة جهد القطب تتأثر بظروف القياس (التركيز ودرجة الحرارة والضغط)، فلكي تكون القيم المسجلة قابلة للمقارنة يجب أن تُقاس جميعها تحت ظروف موحدة هي 1M و25°C و1 atm. وفي المثال المذكور تختلف الظروف (تركيز 0.01M ودرجة حرارة 50°C) عن الظروف القياسية، فلا تُعد القيمة المقيسة جهد اختزال قياسيًا، وقد تختلف عن القيمة −0.7618 V؛ فلا تصح مقارنتها مباشرة بالقيم القياسية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O10' and q.type = 'essay' and q.number = 3) and model_answer = 'لأن قيمة جهد القطب تتأثر بظروف القياس (التركيز ودرجة الحرارة والضغط)، فلكي تكون قيم الجدول قابلة للمقارنة يجب أن تُقاس جميعها تحت ظروف موحدة هي 1M و25°C و1 atm. وفي المثال المذكور تختلف الظروف (تركيز 0.01M ودرجة حرارة 50°C) عن الظروف القياسية، فلا تُعد القيمة المقيسة جهد اختزال قياسيًا، وقد تختلف عن القيمة −0.7618 V المسجلة؛ فلا تصح مقارنتها مباشرة بقيم الجدول.';
