update public.questions set stem = 'يعتقد بعض الناس أن الصدأ مجرد تفاعل بين الحديد والأكسجين. ناقش هذا الاعتقاد في ضوء تعريف التآكل، مستعينًا بالملاحظة الآتية: قطعة حديد في هواء جاف تبقى زمنًا طويلًا دون صدأ يُذكر، بينما تصدأ قطعة مماثلة في هواء رطب، ويصدأ هيكل سفينة في ماء البحر أسرع منهما.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O03' and q.type = 'essay' and q.number = 3) and stem = 'يعتقد بعض الناس أن الصدأ مجرد تفاعل بين الحديد والأكسجين. ناقش هذا الاعتقاد في ضوء تعريف التآكل وما ورد في الكتاب، مستعينًا بالملاحظة الآتية: قطعة حديد في هواء جاف تبقى زمنًا طويلًا دون صدأ يُذكر، بينما تصدأ قطعة مماثلة في هواء رطب، ويصدأ هيكل سفينة في ماء البحر أسرع منهما.';
