update public.question_answers set model_answer = 'أوصي بالبطارية القلوية. الحجج: 1) أكثر كفاءة؛ لأن الخارصين فيها مسحوق يوفر مساحة سطح أكبر للتفاعل. 2) لا تحتاج إلى عمود كربون كاثودًا فيمكن تصنيعها بأحجام صغيرة تناسب الأجهزة الصغيرة. 3) خلية الخارصين والكربون ينخفض جهدها (1.5 V) إلى مستوى غير نافع عندما يبدأ انطلاق غاز الأمونيا الناتج عن تفاعل الاختزال، فلا تناسب الاستعمال الطويل. ويقبل أي حجة علمية صحيحة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O07' and q.type = 'essay' and q.number = 3) and model_answer = 'أوصي بالبطارية القلوية. الحجج: 1) أكثر كفاءة؛ لأن الخارصين فيها مسحوق يوفر مساحة سطح أكبر للتفاعل. 2) لا تحتاج إلى عمود كربون كاثودًا فيمكن تصنيعها بأحجام صغيرة تناسب الأجهزة الصغيرة. 3) خلية الخارصين والكربون ينخفض جهدها (1.5 V) إلى مستوى غير نافع عندما يبدأ انطلاق غاز الأمونيا الناتج عن تفاعل الاختزال، فلا تناسب الاستعمال الطويل.';
