update public.questions set stem = 'في خلية مكوّنة من قطب خارصين في محلول Zn²⁺ وقطب نحاس في محلول Cu²⁺: (أ) اكتب نصفي التفاعل والتفاعل الكلي عندما تعمل خلية جلفانية. (ب) اكتب نصفي التفاعل والتفاعل الكلي عندما توصل بمصدر جهد خارجي فتعمل خلية تحليل كهربائي، محددًا القطب الذي يحدث عنده التأكسد في كل حالة.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O01' and q.type = 'essay' and q.number = 2) and stem = 'في خلية الخارصين والنحاس الموضحة في الشكل 4-19: (أ) اكتب نصفي التفاعل والتفاعل الكلي عندما تعمل خلية جلفانية. (ب) اكتب نصفي التفاعل والتفاعل الكلي عندما توصل بمصدر جهد خارجي فتعمل خلية تحليل كهربائي، محددًا القطب الذي يحدث عنده التأكسد في كل حالة.';
