update public.question_answers set model_answer = 'الخلية الجلفانية: تحول الطاقة الكيميائية إلى طاقة كهربائية، تفاعلها تلقائي، ومصدر طاقتها التفاعل الكيميائي نفسه؛ مثالها خلية الخارصين والنحاس التي تضيء مصباحًا. خلية التحليل الكهربائي: تحول الطاقة الكهربائية إلى طاقة كيميائية، تفاعلها غير تلقائي، ومصدر طاقتها مصدر جهد (طاقة) خارجي؛ مثالها خلية داون أو البطارية الثانوية في أثناء شحنها. ويقبل أي مثال صحيح.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O03' and q.type = 'essay' and q.number = 1) and model_answer = 'الخلية الجلفانية: تحول الطاقة الكيميائية إلى طاقة كهربائية، تفاعلها تلقائي، ومصدر طاقتها التفاعل الكيميائي نفسه؛ مثالها خلية الخارصين والنحاس التي تضيء مصباحًا. خلية التحليل الكهربائي: تحول الطاقة الكهربائية إلى طاقة كيميائية، تفاعلها غير تلقائي، ومصدر طاقتها مصدر جهد (طاقة) خارجي؛ مثالها خلية داون أو البطارية الثانوية في أثناء شحنها.';
update public.questions set stem = 'يمكن لأقطاب الخارصين والنحاس نفسها أن تكوّن خلية جلفانية أو خلية تحليل كهربائي. فسّر كيف يكون ذلك، محددًا في كل حالة: القطب الذي يتأكسد، والقطب الذي يحدث عنده الاختزال، ودور المصباح أو مصدر الجهد في الدائرة.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O03' and q.type = 'essay' and q.number = 2) and stem = 'يبين الشكل 4-19 أن أقطاب الخارصين والنحاس نفسها يمكن أن تكوّن خلية جلفانية أو خلية تحليل كهربائي. فسّر كيف يكون ذلك، محددًا في كل حالة: القطب الذي يتأكسد، والقطب الذي يحدث عنده الاختزال، ودور المصباح أو مصدر الجهد في الدائرة.';
update public.questions set stem = 'احسب جهد خلية داون القياسي باستعمال جهدي الاختزال القياسيين: E°(Na⁺/Na) = −2.71 V و E°(Cl₂/Cl⁻) = +1.358 V، ثم بيّن هل يجب أن يكون هذا الجهد موجبًا أم سالبًا، وقارنه بجهد خلية الخارصين والنحاس الجلفانية (+1.104 V) من حيث دلالته على تلقائية التفاعل ومصدر الطاقة.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O03' and q.type = 'essay' and q.number = 3) and stem = 'احسب جهد خلية داون القياسي باستعمال الجدول 4-1: E°(Na⁺/Na) = −2.71 V و E°(Cl₂/Cl⁻) = +1.358 V، ثم بيّن هل يجب أن يكون هذا الجهد موجبًا أم سالبًا، وقارنه بجهد خلية الخارصين والنحاس الجلفانية (+1.104 V) من حيث دلالته على تلقائية التفاعل ومصدر الطاقة.';
update public.questions set stem = 'استعمل البيانات الآتية: E°(Na⁺/Na) = −2.71 V و E°(2H₂O + 2e⁻ → H₂ + 2OH⁻) = −0.8277 V لتبرير عدم تكوّن الصوديوم عند كاثود خلية ماء البحر، ثم فسّر لماذا يصبح المحلول المحيط بالكاثود قاعديًا، واكتب التفاعل الكلي للخلية.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O04' and q.type = 'essay' and q.number = 2) and stem = 'استعمل البيانات الآتية من الجدول 4-1: E°(Na⁺/Na) = −2.71 V و E°(2H₂O + 2e⁻ → H₂ + 2OH⁻) = −0.8277 V لتبرير عدم تكوّن الصوديوم عند كاثود خلية ماء البحر، ثم فسّر لماذا يصبح المحلول المحيط بالكاثود قاعديًا، واكتب التفاعل الكلي للخلية.';
