update public.question_answers set explanation = 'عند إعادة شحن بطارية ثانوية فإنها تعمل عمل خلية تحليل كهربائي؛ لأن الطاقة الكهربائية تُستعمل لإحداث التفاعل غير التلقائي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O06' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أنه عند إعادة شحن بطارية ثانوية فإنها تعمل عمل خلية تحليل كهربائي؛ لأن الطاقة الكهربائية تُستعمل لإحداث التفاعل غير التلقائي.';
