update public.question_answers set model_answer = 'التحليل الكهربائي: استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي. خلية التحليل الكهربائي: الخلية الكهروكيميائية التي يحدث فيها تحليل كهربائي. من الأمثلة: البطارية الثانوية في أثناء إعادة شحنها، وخلية داون لتحليل مصهور NaCl (ويقبل أي مثال صحيح، ومنه: خلية التحليل الكهربائي لماء البحر، خلية هول–هيروليت، خلية تنقية النحاس، خلية الطلاء بالفضة).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O06' and q.type = 'essay' and q.number = 1) and model_answer = 'التحليل الكهربائي: استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي. خلية التحليل الكهربائي: الخلية الكهروكيميائية التي يحدث فيها تحليل كهربائي. من الأمثلة: البطارية الثانوية في أثناء إعادة شحنها، وخلية داون لتحليل مصهور NaCl (ويقبل: خلية التحليل الكهربائي لماء البحر، خلية هول–هيروليت، خلية تنقية النحاس، خلية الطلاء بالفضة).';
