update public.question_answers set model_answer = 'النواتج: غاز الهيدروجين، وغاز الكلور، ومحلول هيدروكسيد الصوديوم، وجميعها مواد ذات أهمية تجارية. يتكون الهيدروجين عند الكاثود (باختزال الماء)، ويتكون الكلور عند الأنود (بتأكسد Cl⁻). من الاستعمالات: يُستعمل الكلور في صناعة بوليمر كلوريد الفينيل الذي تُصنع منه الأنابيب (ويقبل أي استعمال صحيح، ومنه: تنقية المياه، المبيضات، إنتاج الهيدروجين لاستعمالات تجارية).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O08' and q.type = 'essay' and q.number = 2) and model_answer = 'النواتج: غاز الهيدروجين، وغاز الكلور، ومحلول هيدروكسيد الصوديوم، وجميعها مواد ذات أهمية تجارية. يتكون الهيدروجين عند الكاثود (باختزال الماء)، ويتكون الكلور عند الأنود (بتأكسد Cl⁻). من الاستعمالات: يُستعمل الكلور في صناعة بوليمر كلوريد الفينيل الذي تُصنع منه الأنابيب (ويقبل: تنقية المياه، المبيضات، إنتاج الهيدروجين لاستعمالات تجارية).';
update public.questions set stem = 'تُعد خلية داون ذات أهمية كبيرة لما يؤديه كل من الصوديوم والكلور من دور في حياة كل فرد. وضّح هذه العبارة بأمثلة من حياتك اليومية لكل من الناتجين، مع كتابة نصف التفاعل الذي ينتج كلًّا منهما في الخلية.', updated_at = now() where id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O08' and q.type = 'essay' and q.number = 3) and stem = 'يقول الكتاب: «يمكن تقدير أهمية خلية داون بصورة ممتازة اعتمادًا على أهمية الدور الذي يؤديه كل من الصوديوم والكلور في حياة كل فرد». وضّح هذه العبارة بأمثلة من حياتك اليومية لكل من الناتجين، مع كتابة نصف التفاعل الذي ينتج كلًّا منهما في الخلية.';
